आचार्यान्मातुलान्भ्रातॄन्पुत्रान्पौत्रान्सखींस्तथा।
श्वश‍ुरान्सुहृदश्चैव सेनयोरुभयोरपि ॥ २६ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":326,\"bb\":300,\"url_path\":\"/en/library/bg/1/26/b300/\",\"body_value\":\"tatrāpaśyat sthitān pārthaḥ
pitṝn atha pitāmahān
ācāryān mātulān bhrātṝn
putrān pautrān sakhīṁs tathā
śvaśurān suhṛdaś caiva
senayor ubhayor api\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":327,\"bb\":301,\"url_path\":\"/en/library/bg/1/26/b301/\",\"shadow_value\":\"tatra – there; apaśyat – he could see; sthitān – standing; pārthaḥ – Arjuna; pitṝn – fathers; atha – also; pitāmahān – grandfathers; ācāryān – teachers; mātulān – maternal uncles; bhrātṝn – brothers; putrān – sons; pautrān – grandsons; sakhīn – friends; tathā – too; śvaśurān – fathers-in-law; suhṛdaḥ – well-wishers; ca – also; eva – certainly; senayoḥ – of the armies; ubhayoḥ – of both parties; api – including.\",\"word_for_word_value\":[{\"word\":\"tatra\",\"translation\":\"there\"},{\"word\":\"apaśyat\",\"translation\":\"he could see\"},{\"word\":\"sthitān\",\"translation\":\"standing\"},{\"word\":\"pārthaḥ\",\"translation\":\"Arjuna\"},{\"word\":\"pitṝn\",\"translation\":\"fathers\"},{\"word\":\"atha\",\"translation\":\"also\"},{\"word\":\"pitāmahān\",\"translation\":\"grandfathers\"},{\"word\":\"ācāryān\",\"translation\":\"teachers\"},{\"word\":\"mātulān\",\"translation\":\"maternal uncles\"},{\"word\":\"bhrātṝn\",\"translation\":\"brothers\"},{\"word\":\"putrān\",\"translation\":\"sons\"},{\"word\":\"pautrān\",\"translation\":\"grandsons\"},{\"word\":\"sakhīn\",\"translation\":\"friends\"},{\"word\":\"tathā\",\"translation\":\"too\"},{\"word\":\"śvaśurān\",\"translation\":\"fathers-in-law\"},{\"word\":\"suhṛdaḥ\",\"translation\":\"well-wishers\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"eva\",\"translation\":\"certainly\"},{\"word\":\"senayoḥ\",\"translation\":\"of the armies\"},{\"word\":\"ubhayoḥ\",\"translation\":\"of both parties\"},{\"word\":\"api\",\"translation\":\"including\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":328,\"bb\":302,\"url_path\":\"/en/library/bg/1/26/b302/\",\"body_value\":\"There Arjuna could see, within the midst of the armies of both parties, his fathers, grandfathers, teachers, maternal uncles, brothers, sons, grandsons, friends, and also his fathers-in-law and well-wishers.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":329,\"bb\":303,\"url_path\":\"/en/library/bg/1/26/b303/\",\"body_value\":\"On the battlefield Arjuna could see all kinds of relatives. He could see persons like Bhūriśravā, who were his father’s contemporaries, grandfathers Bhīṣma and Somadatta, teachers like Droṇācārya and Kṛpācārya, maternal uncles like Śalya and Śakuni, brothers like Duryodhana, sons like Lakṣmaṇa, friends like Aśvatthāmā, well-wishers like Kṛtavarmā, etc. He could see also the armies which contained many of his friends.\"}]}],\"short_title\":\"Bg. 1.26\",\"medium_title\":\"Bhagavad-gītā As It Is 1.26\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"a