:\"/en/library/bg/1/28/\",\"bb\":308,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/1/27/\",\"title\":\"TEXT 27\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/1/29/\",\"title\":\"TEXT 29\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":336,\"bb\":567910,\"url_path\":\"/en/library/bg/1/28/devanagari/\",\"body_final\":\"अर्जुन उवाच
दृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम्  ।
सीदन्ति मम गात्राणि मुखं च परिश‍ुष्यति ॥ २८ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":337,\"bb\":310,\"url_path\":\"/en/library/bg/1/28/b310/\",\"body_value\":\"arjuna uvāca
dṛṣṭvemaṁ sva-janaṁ kṛṣṇa
yuyutsuṁ samupasthitam
sīdanti mama gātrāṇi
mukhaṁ ca pariśuṣyati\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":338,\"bb\":311,\"url_path\":\"/en/library/bg/1/28/b311/\",\"shadow_value\":\"arjunaḥ uvāca – Arjuna said; dṛṣṭvā – after seeing; imam – all these; sva-janam – kinsmen; kṛṣṇa – O Kṛṣṇa; yuyutsum – all in a fighting spirit; samupasthitam – present; sīdanti – are quivering; mama – my; gātrāṇi – limbs of the body; mukham – mouth; ca – also; pariśuṣyati – is drying up.\",\"word_for_word_value\":[{\"word\":\"arjunaḥ uvāca\",\"translation\":\"Arjuna said\"},{\"word\":\"dṛṣṭvā\",\"translation\":\"after seeing\"},{\"word\":\"imam\",\"translation\":\"all these\"},{\"word\":\"sva-janam\",\"translation\":\"kinsmen\"},{\"word\":\"kṛṣṇa\",\"translation\":\"O Kṛṣṇa\"},{\"word\":\"yuyutsum\",\"translation\":\"all in a fighting spirit\"},{\"word\":\"samupasthitam\",\"translation\":\"present\"},{\"word\":\"sīdanti\",\"translation\":\"are quivering\"},{\"word\":\"mama\",\"translation\":\"my\"},{\"word\":\"gātrāṇi\",\"translation\":\"limbs of the body\"},{\"word\":\"mukham\",\"translation\":\"mouth\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"pariśuṣyati\",\"translation\":\"is drying up\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":339,\"bb\":312,\"url_path\":\"/en/library/bg/1/28/b312/\",\"body_value\":\"Arjuna said: My dear Kṛṣṇa, seeing my friends and relatives present before me in such a fighting spirit, I feel the limbs of my body quivering and my mouth drying up.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":340,\"bb\":313,\"url_path\":\"/en/library/bg/1/28/b313/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":341,\"bb\":314,\"url_path\":\"/en/library/bg/1/28/b314/\",\"body_value\":\"yasyāsti bhaktir bhagavaty akiñcanā
sarvair guṇais tatra samāsate surāḥ
